18| package org.apache.commons.compress.utils;
19| 
20| import java.io.IOException;
21| import java.io.InputStream;
22| import java.util.zip.Checksum;
23| 
24| /**
25|  * A stream that calculates the checksum of the data read.
26|  * @NotThreadSafe
27|  * @since 1.14
28|  */
29| public class ChecksumCalculatingInputStream extends InputStream {
30|     private final InputStream in;
31|     private final Checksum checksum;
32| 
33|     public ChecksumCalculatingInputStream(final Checksum checksum, final InputStream in) {
34| 
35| 
36| 
37|         this.checksum = checksum;
38|         this.in = in;
39|     }
40| 
41|     /**
42|      * Reads a single byte from the stream
43|      * @throws IOException if the underlying stream throws or the
44|      * stream is exhausted and the Checksum doesn't match the expected
45|      * value
46|      */
47|     @Override
48|     public int read() throws IOException {
49|         final int ret = in.read();
50|         if (ret >= 0) {
51|             checksum.update(ret);
52|         }
53|         return ret;
54|     }
55| 
56|     /**
57|      * Reads a byte array from the stream
58|      * @throws IOException if the underlying stream throws or the
59|      * stream is exhausted and the Checksum doesn't match the expected
60|      * value
61|      */
62|     @Override
63|     public int read(final byte[] b) throws IOException {
64|         return read(b, 0, b.length);
65|     }
66| 
67|     /**
68|      * Reads from the stream into a byte array.
69|      * @throws IOException if the underlying stream throws or the
70|      * stream is exhausted and the Checksum doesn't match the expected
71|      * value
72|      */
73|     @Override
74|     public int read(final byte[] b, final int off, final int len) throws IOException {
75|         final int ret = in.read(b, off, len);
76|         if (ret >= 0) {
77|             checksum.update(b, off, ret);
78|         }
79|         return ret;
80|     }
81| 
82|     @Override
83|     public long skip(final long n) throws IOException {
84|         // Can't really skip, we have to hash everything to verify the checksum
85|         if (read() >= 0) {
86|             return 1;
87|         }
88|         return 0;
89|     }
90| 
91|     /**
92|      * Returns the calculated checksum.
93|      * @return the calculated checksum.
94|      */
95|     public long getValue() {
96|         return checksum.getValue();
97|     }
98| 
99| }
